# frozen_string_literal: true

require "rubygems"

module RapidRailsTemplate
  class Environment
    RUBY_RANGE = Gem::Requirement.new(">= 4.0", "< 4.1")
    RAILS_RANGE = Gem::Requirement.new(">= 8.1", "< 8.2")

    def self.validate!
      ruby_version = Gem::Version.new(RUBY_VERSION)
      raise EnvironmentError, "Ruby #{RUBY_VERSION}は対象外です（4.0.xが必要）" unless RUBY_RANGE.satisfied_by?(ruby_version)

      rails_spec = Gem::Specification.find_all_by_name("rails").select { |spec| RAILS_RANGE.satisfied_by?(spec.version) }.max_by(&:version)
      raise EnvironmentError, "Rails 8.1.xがインストールされていません" if rails_spec.nil?

      rails_spec
    end
  end
end

# frozen_string_literal: true

module RapidRailsTemplate
  class Questionnaire
    Question = Data.define(:id, :prompt, :choices, :default, :condition)

    QUESTIONS = [
      Question.new(:pwa, "PWAを使用しますか？", %w[use skip], "skip", nil),
      Question.new(:web_push, "PWAでWeb Pushを使用しますか？", %w[use skip], "skip", ->(a) { a["pwa"] == "use" }),
      Question.new(:active_job, "ジョブ管理を使用しますか？", %w[solid_queue skip], "skip", nil),
      Question.new(:solid_cache, "Solid Cacheを使用しますか？", %w[use skip], "use", nil),
      Question.new(:account_authentication, "アカウント管理方法を選択してください。", %w[devise wallet_siwe], "devise", nil),
      Question.new(:action_cable, "Action Cableを使用しますか？", %w[solid_cable skip], "skip", nil),
      Question.new(:mail, "メール機能を使用しますか？", %w[auto use skip], "auto", nil),
      Question.new(:action_text, "Action Textを使用しますか？", %w[use skip], "use", nil),
      Question.new(:deployment, "デプロイ方法を選択してください。", %w[dokploy none], "dokploy", nil)
    ].freeze

    def initialize(input: $stdin, output: $stdout)
      @input = input
      @output = output
    end

    def ask_all
      QUESTIONS.each_with_object({}) do |question, answers|
        next unless question.condition.nil? || question.condition.call(answers)

        answers[question.id.to_s] = ask(question)
      end
    end

    def confirm?(summary)
      @output.puts summary
      @output.print "この内容で実行しますか？ [y/N]: "
      %w[y yes].include?(read_line.downcase)
    end

    private

    def ask(question)
      loop do
        @output.print "#{question.prompt} (#{question.choices.join('/')}) [#{question.default}]: "
        answer = read_line
        answer = question.default if answer.empty?
        return answer if question.choices.include?(answer)

        @output.puts "無効な値です: #{answer}"
      end
    end

    def read_line
      value = @input.gets
      raise Error, "入力が終了しました" if value.nil?

      value.strip
    end
  end
end

# frozen_string_literal: true

module RapidRailsTemplate
  class Configuration
    VALID_VALUES = {
      "pwa" => %w[use skip],
      "web_push" => %w[use skip],
      "active_job" => %w[solid_queue skip],
      "solid_cache" => %w[use skip],
      "account_authentication" => %w[devise wallet_siwe],
      "action_cable" => %w[solid_cable skip],
      "mail" => %w[auto use skip],
      "action_text" => %w[use skip],
      "deployment" => %w[dokploy none]
    }.freeze

    DEFAULTS = {
      "pwa" => "skip",
      "web_push" => "skip",
      "active_job" => "skip",
      "solid_cache" => "use",
      "account_authentication" => "devise",
      "action_cable" => "skip",
      "mail" => "auto",
      "action_text" => "use",
      "deployment" => "dokploy"
    }.freeze

    attr_reader :answers, :values, :reasons

    def self.build(answers)
      new(answers).tap(&:validate!)
    end

    def initialize(answers)
      @answers = DEFAULTS.merge(answers.transform_keys(&:to_s)).freeze
      @values = @answers.dup
      @reasons = {}
      normalize!
      @values.freeze
      @reasons.freeze
      freeze
    end

    def [](key)
      values.fetch(key.to_s)
    end

    def to_h
      { "answers" => answers, "values" => values, "reasons" => reasons }
    end

    def validate!
      VALID_VALUES.each do |key, allowed|
        value = answers[key]
        raise InvalidConfiguration, "#{key}が未回答です" if value.nil?
        raise InvalidConfiguration, "#{key}の値が不正です: #{value}" unless allowed.include?(value)
      end
      raise InvalidConfiguration, "PWA無効時にWeb Pushは使用できません" if self["pwa"] == "skip" && self["web_push"] == "use"

      self
    end

    private

    def normalize!
      if @values["pwa"] == "skip"
        @values["web_push"] = "skip"
        @reasons["web_push"] = "PWAを使用しないため"
      end

      return unless @values["mail"] == "auto"

      @values["mail"] = @values["account_authentication"] == "devise" ? "use" : "skip"
      @reasons["mail"] = "認証方式が#{@values['account_authentication']}のため"
    end
  end
end

