module RapidRailsTemplate
  class GeneratorOptions
    FIXED = %w[
      --database=sqlite3
      --asset-pipeline=propshaft
      --javascript=importmap
      --css=tailwind
      --skip-rubocop
      --skip-docker
      --skip-kamal
      --skip-thruster
      --skip-system-test
    ].freeze

    def self.build(configuration)
      options = FIXED.dup
      options.concat(%w[--skip-action-mailer --skip-action-mailbox]) if configuration["mail"] == "skip"
      options << "--skip-action-text" if configuration["action_text"] == "skip"
      options << "--skip-action-cable" if configuration["action_cable"] == "skip"
      options << "--skip-solid" # Solid components are installed individually from the confirmed plan.
      options.freeze
    end
  end
end

# frozen_string_literal: true

module RapidRailsTemplate
  class ExecutionPlan
    attr_reader :configuration, :generator_options, :gems, :steps, :artifacts, :processes

    def self.build(configuration)
      new(configuration)
    end

    def initialize(configuration)
      @configuration = configuration
      @generator_options = GeneratorOptions.build(configuration)
      @gems = build_gems.freeze
      @steps = build_steps.freeze
      @artifacts = build_artifacts.freeze
      @processes = build_processes.freeze
      freeze
    end

    def to_h
      {
        "configuration" => configuration.to_h,
        "generator_options" => generator_options,
        "gems" => gems,
        "steps" => steps,
        "artifacts" => artifacts,
        "processes" => processes
      }
    end

    def summary
      lines = ["\n実行計画", "========", "実効値:"]
      configuration.values.each { |key, value| lines << "  #{key}: #{value}" }
      configuration.reasons.each { |key, reason| lines << "    (#{key}: #{reason})" }
      lines << "rails new options: #{generator_options.join(' ')}"
      lines << "Gem: #{gems.join(', ')}"
      lines << "Steps: #{steps.join(' -> ')}"
      lines << "生成物: #{artifacts.empty? ? '(なし)' : artifacts.join(', ')}"
      lines << "Production processes: #{processes.empty? ? '(未設定)' : processes.join(', ')}"
      lines.join("\n")
    end

    private

    def build_gems
      result = %w[pagy active_link_to action_policy sentry-ruby sentry-rails capybara capybara-playwright-driver factory_bot factory_bot_rails ruby-lsp ruby-lsp-rails rubocop-rails rubocop-thread_safety momocop prism]
      result << "devise" if configuration["account_authentication"] == "devise"
      result << "siwe-rb" if configuration["account_authentication"] == "wallet_siwe"
      result << "web-push" if configuration["web_push"] == "use"
      result << "solid_queue" if configuration["active_job"] == "solid_queue"
      result << "solid_cache" if configuration["solid_cache"] == "use"
      result << "solid_cable" if configuration["action_cable"] == "solid_cable"
      result << "foreman" if configuration["deployment"] == "dokploy"
      result
    end

    def build_steps
      result = %w[declare_gems configure_rubocop configure_test_stack configure_application_gems]
      result << (configuration["account_authentication"] == "devise" ? "install_devise" : "install_wallet_siwe")
      result << "configure_web_push" if configuration["web_push"] == "use"
      result << "install_solid_queue" if configuration["active_job"] == "solid_queue"
      result << "install_solid_cache" if configuration["solid_cache"] == "use"
      result << "install_solid_cable" if configuration["action_cable"] == "solid_cable"
      result << "configure_dokploy" if configuration["deployment"] == "dokploy"
      result << "verify"
      result
    end

    def build_artifacts
      result = []
      result.concat(%w[Dockerfile.prod .dockerignore bin/docker-entrypoint Procfile.prod litestream.yml]) if configuration["deployment"] == "dokploy"
      result << "mise.local.toml" if configuration["web_push"] == "use"
      result
    end

    def build_processes
      return [] unless configuration["deployment"] == "dokploy"

      result = ["web"]
      result << "worker" if configuration["active_job"] == "solid_queue"
      result
    end
  end
end

# frozen_string_literal: true

require "json"
require "open3"
require "rbconfig"
require "tempfile"

module RapidRailsTemplate
  class Runner
    def initialize(app_path:, plan:, template_payload:, output: $stdout, error: $stderr, process_runner: Open3)
      @app_path = app_path
      @plan = plan
      @template_payload = template_payload
      @output = output
      @error = error
      @process_runner = process_runner
    end

    def run
      template_file = secure_tempfile(["rapid-rails-template", ".rb"], template_payload)
      config_file = secure_tempfile(["rapid-rails-configuration", ".json"], JSON.generate(plan.to_h))
      command = rails_command(template_file.path)
      environment = { "RAPID_RAILS_TEMPLATE_CONFIG" => config_file.path }
      status = stream_process(environment, command)
      status.exitstatus || 1
    ensure
      template_file&.close!
      config_file&.close!
    end

    private

    attr_reader :app_path, :plan, :template_payload, :output, :error, :process_runner

    def secure_tempfile(basename, content)
      file = Tempfile.new(basename)
      file.chmod(0o600)
      file.binmode
      file.write(content)
      file.flush
      file
    end

    def rails_command(template_path)
      rails = Gem.bin_path("railties", "rails", ">= 8.1", "< 8.2")
      [RbConfig.ruby, rails, "new", app_path, *plan.generator_options, "--template", template_path]
    end

    def stream_process(environment, command)
      process_runner.popen3(environment, *command) do |stdin, stdout, stderr, wait_thread|
        stdin.close
        readers = [Thread.new { IO.copy_stream(stdout, output) }, Thread.new { IO.copy_stream(stderr, error) }]
        readers.each(&:join)
        wait_thread.value
      end
    rescue SystemCallError => e
      raise Error, "rails newを起動できません: #{e.message}"
    end
  end
end


require "base64"
module RapidRailsTemplate
  APPLICATION_TEMPLATE = Base64.strict_decode64("").freeze
end

# frozen_string_literal: true

module RapidRailsTemplate
  class Entrypoint
    def self.run(argv, input: $stdin, output: $stdout, error: $stderr, runner_class: Runner)
      defaults_mode, app_path = parse_arguments(argv)

      Environment.validate!
      questionnaire = Questionnaire.new(input:, output:) unless defaults_mode
      configuration = defaults_mode ? Configuration.build({}) : Configuration.build(questionnaire.ask_all)
      plan = ExecutionPlan.build(configuration)
      if defaults_mode
        output.puts plan.summary
      else
        return 0 unless questionnaire.confirm?(plan.summary)
      end

      runner_class.new(app_path:, plan:, template_payload: APPLICATION_TEMPLATE, output:, error:).run
    rescue Error => e
      error.puts "エラー: #{e.message}"
      1
    end

    def self.parse_arguments(argv)
      return [false, argv.fetch(0)] if argv.length == 1
      return [true, argv.fetch(1)] if argv.length == 2 && argv.fetch(0) == "--defaults"

      raise Error, "使用方法: ruby bootstrap.rb [--defaults] APP_PATH"
    end

    private_class_method :parse_arguments
  end
end

exit RapidRailsTemplate::Entrypoint.run(ARGV) if $PROGRAM_NAME == __FILE__
